-- M2 contract DDL v1. Cross-owner UUIDs are references, never foreign keys.
SET LOCAL timezone = 'UTC';
CREATE TABLE catalog.categories (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), code text NOT NULL UNIQUE, name text NOT NULL, active boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE ON catalog.categories TO helpdesk_m2;
CREATE TABLE catalog.services (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), code text NOT NULL UNIQUE, name text NOT NULL, owner_org_id uuid NOT NULL, access_mode text NOT NULL CHECK(access_mode IN ('PUBLIC_GUEST','PUBLIC_AUTH','ASN_AUTH','STAFF_ONLY')), category_id uuid REFERENCES catalog.categories(id), active boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE ON catalog.services TO helpdesk_m2;
CREATE TABLE catalog.service_forms (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), service_id uuid NOT NULL REFERENCES catalog.services(id), form_version integer NOT NULL CHECK(form_version>0), fields jsonb NOT NULL CHECK(jsonb_typeof(fields)='array'), UNIQUE(service_id,form_version));
GRANT SELECT, INSERT, UPDATE ON catalog.service_forms TO helpdesk_m2;
CREATE TABLE catalog.policies (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), service_id uuid NOT NULL REFERENCES catalog.services(id), policy_version integer NOT NULL CHECK(policy_version>0), upload_max_bytes bigint NOT NULL CHECK(upload_max_bytes BETWEEN 1 AND 10485760), allowed_mime text[] NOT NULL, audience_org_ids uuid[] NOT NULL, effective_at timestamptz NOT NULL, UNIQUE(service_id,policy_version));
GRANT SELECT, INSERT, UPDATE ON catalog.policies TO helpdesk_m2;
CREATE TABLE catalog.portal_navigation (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), route text NOT NULL CHECK(route ~ '^/[^/]' OR route='/'), label text NOT NULL, audience text NOT NULL CHECK(audience IN ('PUBLIC_GUEST','PUBLIC_AUTH','ASN_AUTH','STAFF_ONLY')), position integer NOT NULL CHECK(position>=0), feature_code text NOT NULL);
GRANT SELECT, INSERT, UPDATE ON catalog.portal_navigation TO helpdesk_m2;
CREATE TABLE catalog.feature_registry (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), code text NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT false, permission text NOT NULL);
GRANT SELECT, INSERT, UPDATE ON catalog.feature_registry TO helpdesk_m2;
CREATE TABLE catalog.idempotency_records (actor_scope text NOT NULL, command text NOT NULL, target text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), payload_digest bytea NOT NULL CHECK(octet_length(payload_digest)=32), response_status integer NOT NULL CHECK(response_status BETWEEN 200 AND 299), response_body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, PRIMARY KEY(actor_scope,command,target,key));
CREATE TABLE catalog.outbox (event_id uuid PRIMARY KEY, event_type text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), occurred_at timestamptz NOT NULL, correlation_id uuid NOT NULL, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'), digest bytea NOT NULL CHECK(octet_length(digest)=32));
CREATE TABLE catalog.outbox_delivery (event_id uuid NOT NULL REFERENCES catalog.outbox(event_id), consumer_id text NOT NULL CHECK(consumer_id ~ '^M[1-9]$'), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), lease_until timestamptz, acked_at timestamptz, last_error_code text, PRIMARY KEY(event_id,consumer_id), CHECK((state='ACKED')=(acked_at IS NOT NULL)));
CREATE TABLE catalog.inbox (consumer_id text NOT NULL, event_id uuid NOT NULL, digest bytea NOT NULL CHECK(octet_length(digest)=32), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE catalog.audit_intents (id uuid PRIMARY KEY, actor_id uuid NOT NULL, action text NOT NULL, object_id uuid NOT NULL, scope text NOT NULL, reason text NOT NULL, outcome text NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON catalog.idempotency_records, catalog.outbox, catalog.inbox, catalog.audit_intents TO helpdesk_m2;
GRANT SELECT, INSERT, UPDATE ON catalog.outbox_delivery TO helpdesk_m2;
CREATE INDEX ON catalog.outbox_delivery (state, lease_until, event_id) WHERE state<>'ACKED';
REVOKE ALL ON ALL TABLES IN SCHEMA catalog FROM PUBLIC;
